import {WORK} from './data.js?v=0.8.0';
import {inReach} from './interactions.js?v=0.8.0';
export function fieldPoint(action,index){return action==='trash'?WORK.cleaning[index]&&{x:WORK.cleaning[index][0],z:WORK.cleaning[index][1]}:action==='crate'?WORK.crate:action==='shelf'?WORK.shelves[index]:null;}
export function beginFieldWork(model,action,index=0){const s=model.s,j=s.job;if(!j||j.fieldAction||s.transit||s.inside||s.riding||!inReach(s.position,fieldPoint(action,index),'work'))return false;if(action==='trash'&&(j.type!=='cleaning'||j.cleaned?.includes(index))||action==='crate'&&(j.type!=='warehouse'||j.carrying)||action==='shelf'&&(j.type!=='warehouse'||!j.carrying||j.progress!==index))return false;if(!['trash','crate','shelf'].includes(action))return false;j.fieldAction={action,index,elapsed:0,duration:action==='trash'?1.2:action==='crate'?1.6:1.0};return true;}
export function tickFieldWork(model,dt){const s=model.s,a=s.job?.fieldAction;if(!a||!Number.isFinite(dt)||dt<=0)return;if(s.inside||s.riding||!inReach(s.position,fieldPoint(a.action,a.index),'work')){delete s.job.fieldAction;return;}a.elapsed+=dt;if(a.elapsed>=a.duration){delete s.job.fieldAction;model.work(a.action,a.index);}}
